"use client";

import {
    TrendingUp,
    Users,
    FileCheck,
    Clock,
    ArrowUpRight,
    ArrowDownRight,
    Plus,
    Filter,
    Zap,
    Wallet,
    Award,
    Flame
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useSimulation } from "@/components/SimulationProvider";
import useSWR from "swr";
import { fetcher } from "@/lib/fetcher";

export default function Dashboard() {
    const { currentUser } = useSimulation();

    const { data: qCertificates } = useSWR('/api/certificates', fetcher);
    const { data: qCustomers } = useSWR('/api/customers', fetcher);

    const certCount = qCertificates?.length || 0;
    const custCount = qCustomers?.length || 0;

    // XP Logic calculation for progress
    const xpGoal = currentUser.level === "Bronze" ? 1000 : currentUser.level === "Prata" ? 2500 : 5000;
    const xpProgress = (currentUser.xp / xpGoal) * 100;

    return (
        <div className="p-4 lg:p-8 space-y-8">
            {/* Hero Section - Gamified */}
            <section className="relative overflow-hidden bg-slate-900 rounded-[2.5rem] p-8 lg:p-12 text-white shadow-2xl">
                <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
                    <div>
                        <div className="flex items-center gap-3 mb-6">
                            <div className="px-3 py-1 bg-primary rounded-full text-[10px] font-black uppercase tracking-widest animate-pulse">
                                Nível {currentUser.level}
                            </div>
                            <div className="flex items-center gap-1.5 text-amber-400 text-xs font-bold">
                                <Flame size={14} />
                                5 Dias de Sequência
                            </div>
                        </div>
                        <h1 className="text-3xl lg:text-5xl font-black mb-6 leading-tight">
                            Boas vendas, <br />
                            <span className="text-primary">{currentUser.name}</span>
                        </h1>

                        {/* XP Progress Bar */}
                        <div className="mb-8 max-w-md">
                            <div className="flex justify-between items-end mb-2">
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Progresso para {currentUser.level === 'Bronze' ? 'Prata' : currentUser.level === 'Prata' ? 'Ouro' : 'Mestre'}</p>
                                <p className="text-sm font-black text-white">{currentUser.xp} <span className="text-slate-500">/ {xpGoal} XP</span></p>
                            </div>
                            <div className="h-3 w-full bg-slate-800 rounded-full overflow-hidden border border-slate-700">
                                <div
                                    className="h-full bg-gradient-to-r from-primary to-indigo-500 rounded-full shadow-[0_0_15px_rgba(59,130,246,0.5)] transition-all duration-1000"
                                    style={{ width: `${xpProgress}%` }}
                                />
                            </div>
                        </div>

                        <div className="flex flex-wrap gap-4">
                            <button className="bg-primary text-white px-8 py-4 rounded-2xl font-black text-sm shadow-xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center gap-3">
                                <Plus size={20} />
                                Nova Emissão
                            </button>
                            <button className="bg-white/5 backdrop-blur-md border border-white/10 text-white px-8 py-4 rounded-2xl font-black text-sm hover:bg-white/10 transition-all flex items-center gap-3">
                                <ArrowUpRight size={20} />
                                Metas do Mês
                            </button>
                        </div>
                    </div>

                    <div className="hidden lg:grid grid-cols-2 gap-6">
                        <div className="bg-white/5 backdrop-blur-sm border border-white/10 rounded-3xl p-6 flex flex-col items-center text-center">
                            <div className="size-12 rounded-2xl bg-amber-500/20 text-amber-500 flex items-center justify-center mb-4">
                                <Award size={24} />
                            </div>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Badge Ativa</p>
                            <p className="text-sm font-black text-white italic">"{currentUser.equippedBadge || 'Nenhum'}"</p>
                        </div>
                        <div className="bg-white/5 backdrop-blur-sm border border-white/10 rounded-3xl p-6 flex flex-col items-center text-center">
                            <div className="size-12 rounded-2xl bg-emerald-500/20 text-emerald-500 flex items-center justify-center mb-4">
                                <Zap size={24} />
                            </div>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Missões Hoje</p>
                            <p className="text-sm font-black text-white">2 / 3 Completas</p>
                        </div>
                    </div>
                </div>

                {/* Abstract Visual Elements */}
                <div className="absolute top-0 right-0 w-1/3 h-full bg-primary/5 blur-3xl -z-10 animate-pulse"></div>
            </section>

            {/* KPI Cards - Enhanced */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-6">
                <StatCard
                    title="Vendas do Mês"
                    value={currentUser.sales_total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                    change="+12.5%"
                    isPositive={true}
                    icon={TrendingUp}
                    color="blue"
                />
                <StatCard
                    title="Sua Wallet"
                    value={currentUser.wallet.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                    change="+R$ 45,00"
                    isPositive={true}
                    icon={Wallet}
                    color="emerald"
                />
                <StatCard
                    title="Meta de XP"
                    value={currentUser.xp.toString()}
                    change={`${Math.floor(xpProgress)}%`}
                    isPositive={true}
                    icon={Award}
                    color="amber"
                />
                <StatCard
                    title="Certificados"
                    value={certCount.toString()}
                    change="+3"
                    isPositive={true}
                    icon={FileCheck}
                    color="indigo"
                />
            </div>

            {/* Middle Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-8 shadow-sm">
                    <div className="flex items-center justify-between mb-8">
                        <div>
                            <h3 className="text-xl font-black tracking-tight">Missões Ativas</h3>
                            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Conclua para ganhar XP extra</p>
                        </div>
                    </div>

                    <div className="space-y-4">
                        <MissionItem
                            title="Venda em Sequência"
                            desc="Realize 1 venda hoje para manter sua ofensiva de 5 dias."
                            progress={100}
                            xp={50}
                            completed
                        />
                        <MissionItem
                            title="Especialista PJ"
                            desc="Emita 3 certificados PJ nesta semana."
                            progress={66}
                            xp={150}
                        />
                        <MissionItem
                            title="Indicação Premiada"
                            desc="Indique 1 contador para a plataforma."
                            progress={0}
                            xp={500}
                        />
                    </div>
                </div>

                <div className="bg-slate-900 rounded-[2rem] p-8 border border-slate-800 shadow-xl self-start">
                    <h3 className="text-white text-lg font-black mb-6 flex items-center gap-2">
                        <Award className="text-primary" size={20} />
                        Selos Equipados
                    </h3>
                    <div className="space-y-6">
                        <div className="p-4 rounded-2xl bg-white/5 border border-white/10 flex items-center gap-4 relative group hover:bg-white/10 transition-all cursor-pointer">
                            <div className="size-12 rounded-xl bg-primary text-white flex items-center justify-center shadow-lg shadow-primary/20">
                                <Zap size={24} />
                            </div>
                            <div>
                                <p className="text-xs font-black text-white uppercase tracking-tight">Selo Start</p>
                                <p className="text-[10px] text-slate-400 font-bold italic">Preços de nível Prata ativos</p>
                            </div>
                            <div className="absolute -top-1 -right-1 size-3 bg-emerald-500 rounded-full border-2 border-slate-900"></div>
                        </div>

                        <div className="p-4 rounded-2xl border-2 border-dashed border-slate-800 flex items-center gap-4 opacity-40 hover:opacity-100 transition-all cursor-pointer">
                            <div className="size-12 rounded-xl bg-slate-800 text-slate-500 flex items-center justify-center">
                                <Award size={24} />
                            </div>
                            <div>
                                <p className="text-xs font-black text-slate-300 uppercase tracking-tight">Vazio</p>
                                <p className="text-[10px] text-slate-500 font-bold">Equipe um selo de buff</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

function MissionItem({ title, desc, progress, xp, completed }: any) {
    return (
        <div className={cn(
            "p-5 rounded-2xl border transition-all flex items-center gap-6",
            completed ? "bg-emerald-500/5 border-emerald-500/20" : "bg-slate-50 dark:bg-slate-900/50 border-slate-100 dark:border-slate-800 hover:border-primary/20"
        )}>
            <div className={cn(
                "size-12 rounded-xl flex items-center justify-center shrink-0",
                completed ? "bg-emerald-500 text-white" : "bg-white dark:bg-slate-800 text-slate-400 shadow-sm"
            )}>
                {completed ? <FileCheck size={24} /> : <Clock size={24} />}
            </div>
            <div className="flex-1">
                <div className="flex justify-between items-center mb-1">
                    <p className="font-black text-sm tracking-tight">{title}</p>
                    <p className="text-[10px] font-bold text-indigo-500 uppercase">+{xp} XP</p>
                </div>
                <p className="text-xs text-slate-500 mb-3">{desc}</p>
                <div className="h-1.5 w-full bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden">
                    <div className={cn("h-full rounded-full transition-all duration-500", completed ? "bg-emerald-500" : "bg-primary")} style={{ width: `${progress}%` }} />
                </div>
            </div>
        </div>
    );
}

function StatCard({ title, value, change, isPositive, icon: Icon, color }: any) {
    const colorMap: any = {
        blue: "bg-blue-500",
        emerald: "bg-emerald-500",
        amber: "bg-amber-500",
        indigo: "bg-indigo-500",
    };

    return (
        <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm hover:shadow-md transition-shadow">
            <div className="flex items-center justify-between mb-4">
                <div className={cn("size-10 rounded-2xl flex items-center justify-center text-white shadow-lg", colorMap[color])}>
                    <Icon size={20} />
                </div>
                <div className={cn(
                    "flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-bold",
                    isPositive ? "bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20" : "bg-rose-50 text-rose-600 dark:bg-rose-900/20"
                )}>
                    {isPositive ? <ArrowUpRight size={12} /> : <ArrowDownRight size={12} />}
                    {change}
                </div>
            </div>
            <div>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">{title}</p>
                <h4 className="text-2xl font-black">{value}</h4>
            </div>
        </div>
    );
}
